-- External project only: run after db/schema.sql. Safe to rerun.
begin;
alter table public.cards add column if not exists deck text not null default 'oracle';
alter table public.cards add column if not exists arcana text;
alter table public.cards add column if not exists suit text;
alter table public.cards add column if not exists sort_order integer;
alter table public.cards add column if not exists numeral text;
update public.cards set sort_order = number - 1 where deck = 'oracle' and sort_order is null;
create unique index if not exists cards_deck_sort_order_idx on public.cards (deck, sort_order);
on conflict (id) do nothing;
commit;
